using System.Net;
using System.Net.Sockets;
using System.Text;
using Finance.Core.Market;
using Finance.Execution.Brokers;
using Finance.Execution.Oms;

namespace Finance.Data.Tests;

/// <summary>
/// TWS order placement against a scripted fake TWS on a loopback socket. The expected placeOrder field lists below
/// are written out literally from the TWS API's <c>EClient.placeOrder</c> (server-version guards noted per field),
/// not generated by the client's encoder, and the server's replies (orderStatus, openOrder, execDetails,
/// commissionReport, error) are raw frames in each message's documented layout.
/// </summary>
public class TwsOrderTests
{
    /// <summary>A fake TWS: version handshake, startApi, managedAccounts + nextValidId 1001, then scripted replies.</summary>
    private sealed class FakeTws : IAsyncDisposable
    {
        private readonly TcpListener _listener = new(IPAddress.Loopback, 0);
        private readonly Task _server;
        public readonly List<string[]> Requests = new();

        public FakeTws(int serverVersion, Func<string[], Func<string[], Task>, Task> onRequest, CancellationToken ct)
        {
            _listener.Start();
            Port = ((IPEndPoint)_listener.LocalEndpoint).Port;
            _server = Task.Run(async () =>
            {
                using var c = await _listener.AcceptTcpClientAsync(ct);
                var s = c.GetStream();
                var prefix = new byte[4];
                await s.ReadExactlyAsync(prefix, ct);
                var len = new byte[4];
                await s.ReadExactlyAsync(len, ct);
                if (BitConverter.IsLittleEndian) Array.Reverse(len);
                await s.ReadExactlyAsync(new byte[BitConverter.ToInt32(len)], ct);
                await s.WriteAsync(Frame(serverVersion.ToString(), "20251012 09:30:00 EST"), ct);
                await ReadFrame(s, ct);                                         // startApi
                await s.WriteAsync(Frame("15", "1", "DU111"), ct);
                await s.WriteAsync(Frame("9", "1", "1001"), ct);
                Task Send(string[] fields) => s.WriteAsync(Frame(fields), ct).AsTask();
                while (true)
                {
                    string[] req;
                    try { req = await ReadFrame(s, ct); } catch { break; }
                    lock (Requests) Requests.Add(req);
                    await onRequest(req, Send);
                }
            }, ct);
        }

        public int Port { get; }

        public string[] Request(string msgId)
        {
            lock (Requests) return Requests.Last(r => r[0] == msgId);
        }

        public async ValueTask DisposeAsync()
        {
            _listener.Stop();
            try { await _server; } catch (OperationCanceledException) { }
        }

        private static byte[] Frame(params string[] fields)
        {
            var body = Encoding.ASCII.GetBytes(string.Concat(fields.Select(f => f + "\0")));
            var len = BitConverter.GetBytes(body.Length);
            if (BitConverter.IsLittleEndian) Array.Reverse(len);
            return len.Concat(body).ToArray();
        }

        private static async Task<string[]> ReadFrame(NetworkStream s, CancellationToken ct)
        {
            var len = new byte[4];
            await s.ReadExactlyAsync(len, ct);
            if (BitConverter.IsLittleEndian) Array.Reverse(len);
            var body = new byte[BitConverter.ToInt32(len)];
            await s.ReadExactlyAsync(body, ct);
            var text = Encoding.ASCII.GetString(body);
            return (text.EndsWith('\0') ? text[..^1] : text).Split('\0');
        }
    }

    private static async Task Until(Func<bool> condition, CancellationToken ct)
    {
        for (int i = 0; i < 200 && !condition(); i++) await Task.Delay(10, ct);
        Assert.True(condition(), "timed out waiting for the fake TWS");
    }

    private const string Unset = "1.7976931348623157E308";

