    // placeOrder at server version 130 (< 145: VERSION 45 follows the message id; fields from 138 on are absent) for
    // SELL 2 ES Dec-25 future STP LMT stop 5000 limit 4995 DAY on CME, account DU111, orderRef T2.
    private static readonly string[] ExpectedStpLmt130 =
    {
        "3", "45", "1001",
        "0", "ES", "FUT", "202512", "0", "", "50", "CME", "", "USD", "", "", "", "",
        "SELL", "2", "STP LMT", "4995", "5000",
