        "0", "", "", "", "", "", "", "0",
        "", "", "", "",
    };

    [Fact]
    public async Task PlaceOrderSendsTheExactFieldSequenceAndTheBrokerReportsFills()
    {
        var ct = TestContext.Current.CancellationToken;
        const string exec1 = "0000e0d5.6578a1b2.01.01", exec2 = "0000e0d5.6578a1b3.01.01";
        await using var fake = new FakeTws(176, async (req, send) =>
        {
            if (req[0] != "3") return;
            string id = req[1];
            // openOrder (>= 145: no version): orderId, contract (conId..tradingClass), action, qty, type, lmt, aux, tif,
            // ocaGroup, account, openClose, origin, orderRef, clientId, permId, outsideRth, hidden, ... (trimmed)
            await send(new[] { "5", id, "265598", "AAPL", "STK", "", "0", "", "", "SMART", "USD", "AAPL", "NMS",
                "BUY", "100", "LMT", "185.5", Unset, "GTC", "", "DU111", "", "0", "T1", "7", "123456", "1", "0", "0" });
            // orderStatus (>= 131: no version): orderId, status, filled, remaining, avgFillPrice, permId, parentId,
            // lastFillPrice, clientId, whyHeld, mktCapPrice
            await send(new[] { "3", id, "Submitted", "0", "100", "0", "123456", "0", "0", "7", "", "0" });
            // execDetails (>= 136: no version): reqId, orderId, contract..., execId, time, acct, exchange, side, shares,
            // price, permId, clientId, liquidation, cumQty, avgPrice, orderRef, evRule, evMultiplier, modelCode, lastLiquidity
            await send(new[] { "11", "-1", id, "265598", "AAPL", "STK", "", "0", "", "", "SMART", "USD", "AAPL", "NMS",
                exec1, "20251012 09:31:00", "DU111", "ISLAND", "BOT", "60", "185.4", "123456", "7", "0", "60", "185.4", "T1", "", "", "", "2" });
            await send(new[] { "59", "1", exec1, "0.3", "USD", Unset, Unset, "" });
            await send(new[] { "3", id, "Submitted", "60", "40", "185.4", "123456", "0", "185.4", "7", "", "0" });
            // A correction of the first execution (same execId up to the last '.') must not be counted twice.
            await send(new[] { "11", "-1", id, "265598", "AAPL", "STK", "", "0", "", "", "SMART", "USD", "AAPL", "NMS",
                "0000e0d5.6578a1b2.01.02", "20251012 09:31:00", "DU111", "ISLAND", "BOT", "60", "185.4", "123456", "7", "0", "60", "185.4", "T1", "", "", "", "2" });
            await send(new[] { "11", "-1", id, "265598", "AAPL", "STK", "", "0", "", "", "SMART", "USD", "AAPL", "NMS",
                exec2, "20251012 09:31:02", "DU111", "ARCA", "BOT", "40", "185.5", "123456", "7", "0", "100", "185.44", "T1", "", "", "", "1" });
            await send(new[] { "59", "1", exec2, "0.2", "USD", Unset, Unset, "" });
            await send(new[] { "3", id, "Filled", "100", "0", "185.44", "123456", "0", "185.5", "7", "", "0" });
        }, ct);

        await using var tws = await TwsClient.ConnectAsync("127.0.0.1", fake.Port, clientId: 7, ct);
        var opens = new List<TwsOpenOrder>();
        tws.OpenOrder += opens.Add;
        await using var broker = new TwsBroker(tws) { Account = "DU111", OutsideRth = true };
        var events = new List<OrderEventKind>();
        broker.OrderUpdated += e => { lock (events) events.Add(e.Kind); };

        var order = new Order("AAPL", Side.Buy, 100, OrderType.Limit, 185.5) { Tag = "T1" };    // TimeInForce defaults to GTC
        await broker.SubmitAsync(order, ct);
        Assert.Equal(1001, broker.TwsOrderId(order.Id));
        Assert.Equal(ExpectedLmt176, fake.Request("3"));

        await Until(() => order.Status == OrderStatus.Filled && broker.ReportedCommission(order.Id) > 0.45, ct);
        var fills = broker.Store.FillsOf(order.Id);
        Assert.Equal(2, fills.Count);
        Assert.Equal((60.0, 185.4), (fills[0].Quantity, fills[0].Price));
        Assert.Equal((40.0, 185.5), (fills[1].Quantity, fills[1].Price));
        Assert.Equal((60 * 185.4 + 40 * 185.5) / 100, order.AverageFillPrice, 9);
        Assert.Equal(0.5, broker.ReportedCommission(order.Id), 12);
        lock (events)
            Assert.Equal(new[] { OrderEventKind.Submitted, OrderEventKind.Accepted, OrderEventKind.PartiallyFilled, OrderEventKind.Filled }, events);

        var open = Assert.Single(opens);
        Assert.Equal((1001L, "AAPL", "LMT", 185.5, (double?)null, "DU111", 123456L, true),
            (open.OrderId, open.Contract.Symbol, open.OrderType, open.LimitPrice!.Value, open.AuxPrice, open.Account, open.PermId, open.OutsideRth));
        Assert.Equal(1002, tws.NextValidOrderId);
    }

    [Fact]
    public async Task OlderServerVersionGuardsFieldsAndDecodesVersionedMessages()
    {
        var ct = TestContext.Current.CancellationToken;
        await using var fake = new FakeTws(130, async (req, send) =>
        {
            switch (req[0])
            {
                case "3":
                    // orderStatus (< 131: version field, no mktCapPrice)
                    await send(new[] { "3", "6", req[2], "PreSubmitted", "0", "2", "0", "555", "0", "0", "7", "" });
                    // execDetails (< 136: version 10 follows the id)
                    await send(new[] { "11", "10", "-1", req[2], "495512563", "ES", "FUT", "20251219", "0", "", "50", "CME", "USD", "ESZ5", "ES",
                        "0000f00d.1.01.01", "20251012 10:00:00", "DU111", "CME", "SLD", "1", "4996", "555", "7", "0", "1", "4996", "T2", "", "", "" });
                    break;
                case "4":
                    await send(new[] { "3", "6", req[2], "Cancelled", "1", "1", "4996", "555", "0", "4996", "7", "" });
                    await send(new[] { "4", "2", req[2], "202", "Order Canceled - reason:" });
                    break;
            }
        }, ct);

        await using var tws = await TwsClient.ConnectAsync("127.0.0.1", fake.Port, clientId: 7, ct);
        Assert.Equal(130, tws.ServerVersion);
        var statuses = new List<TwsOrderStatus>();
        tws.OrderStatus += s => { lock (statuses) statuses.Add(s); };
        await using var broker = new TwsBroker(tws) { Account = "DU111" };
        broker.RegisterContract("ES", TwsContract.Future("ES", "202512", "CME", multiplier: "50"));

        var order = new Order("ES", Side.Sell, 2, OrderType.StopLimit, limitPrice: 4995, stopPrice: 5000) { TimeInForce = TimeInForce.Day, Tag = "T2" };
        await broker.SubmitAsync(order, ct);
        Assert.Equal(ExpectedStpLmt130, fake.Request("3"));

        await Until(() => order.FilledQuantity == 1, ct);
        Assert.Equal(OrderStatus.PartiallyFilled, order.Status);
        Assert.Equal(4996, broker.Store.FillsOf(order.Id).Single().Price);
        lock (statuses) Assert.Equal(("PreSubmitted", 555L, 2.0, "", 0.0), (statuses[0].Status, statuses[0].PermId, statuses[0].Remaining, statuses[0].WhyHeld, statuses[0].MarketCapPrice));

        Assert.True(await broker.CancelAsync(order.Id, ct));
        Assert.Equal(OrderStatus.Cancelled, order.Status);
        Assert.Equal(new[] { "4", "1", "1001" }, fake.Request("4"));          // < 169: no manualOrderCancelTime
        Assert.False(await broker.CancelAsync(order.Id, ct));                 // no longer open
    }

    [Fact]
    public async Task ForexStopRejectedByErrorAndOpenOrdersListed()
    {
        var ct = TestContext.Current.CancellationToken;
        await using var fake = new FakeTws(176, async (req, send) =>
        {
            switch (req[0])
            {
                case "3":
                    await send(new[] { "4", "2", req[1], "201", "Order rejected - reason:Insufficient margin", "" });
                    break;
                case "5":   // reqOpenOrders
                    await send(new[] { "5", "990", "12087792", "EUR", "CASH", "", "0", "", "", "IDEALPRO", "USD", "EUR.USD", "EUR.USD",
                        "SELL", "20000", "STP", Unset, "1.07", "GTC", "", "DU111", "", "0", "", "7", "88001", "0", "0" });
                    await send(new[] { "5", "991", "495512563", "ES", "FUT", "20251219", "0", "", "50", "CME", "USD", "ESZ5", "ES",
                        "BUY", "1", "STP LMT", "5101", "5100", "DAY", "", "DU111", "", "0", "", "7", "88002", "1", "0" });
                    await send(new[] { "53", "1" });
                    break;
            }
        }, ct);

        await using var tws = await TwsClient.ConnectAsync("127.0.0.1", fake.Port, clientId: 7, ct);
        await using var broker = new TwsBroker(tws);
        broker.RegisterContract("EURUSD", TwsContract.Forex("EUR/USD"));
        var order = Order.StopMarket("EURUSD", Side.Sell, 20_000, 1.07);
        await broker.SubmitAsync(order, ct);
        Assert.Equal(OrderStatus.Rejected, order.Status);
        Assert.Contains("201", broker.Store.History.Last().Message);

        var place = fake.Request("3");
        Assert.Equal(new[] { "0", "EUR", "CASH", "", "0", "", "", "IDEALPRO", "", "USD" }, place[2..12]);
        Assert.Equal(new[] { "SELL", "20000", "STP", "", "1.07", "GTC", "", "" }, place[16..24]);   // no account set: TWS default

        var open = await tws.GetOpenOrdersAsync(ct);
        Assert.Equal(2, open.Count);
        Assert.Equal(("CASH", "EUR", "USD", "STP", (double?)null, 1.07), (open[0].Contract.SecType, open[0].Contract.Symbol, open[0].Contract.Currency, open[0].OrderType, open[0].LimitPrice, open[0].AuxPrice!.Value));
        Assert.Equal(("FUT", "20251219", 5101.0, 5100.0, true), (open[1].Contract.SecType, open[1].Contract.LastTradeDateOrContractMonth, open[1].LimitPrice!.Value, open[1].AuxPrice!.Value, open[1].OutsideRth));
        Assert.Equal(new[] { "5", "1" }, fake.Request("5"));

        // cancelOrder at 176 (>= 169) carries an empty manualOrderCancelTime.
        await tws.CancelOrderAsync(990, ct);
        await Until(() => { lock (fake.Requests) return fake.Requests.Any(r => r[0] == "4"); }, ct);
        Assert.Equal(new[] { "4", "1", "990", "" }, fake.Request("4"));
    }

    [Fact]
    public void MappingAndValidation()
    {
        var stp = TwsBroker.ToTwsOrder(new Order("AAPL", Side.Sell, 10, OrderType.Stop, stopPrice: 180) { TimeInForce = TimeInForce.Ioc, TriggerBy = TriggerPriceType.Last });
        Assert.Equal(("SELL", "STP", 180.0, (double?)null, "IOC", 2), (stp.Action, stp.OrderType, stp.AuxPrice!.Value, stp.LimitPrice, stp.Tif, stp.TriggerMethod));
        Assert.Throws<BrokerException>(() => TwsBroker.ToTwsOrder(new Order("AAPL", Side.Buy, 1) { TimeInForce = TimeInForce.Fok }));
        Assert.Throws<BrokerException>(() => TwsBroker.ToTwsOrder(new Order("AAPL", Side.Buy, 1) { TakeProfitPrice = 200 }));
        Assert.Throws<BrokerException>(() => TwsBroker.ToTwsOrder(new Order("AAPL", Side.Buy, 1, OrderType.Stop, stopPrice: 1) { TriggerBy = TriggerPriceType.Mark }));

        var c = TwsContract.Stock("aapl");
        Assert.Throws<NotSupportedException>(() => TwsPlaceOrder.Fields(177, 1, c, TwsOrder.Market("BUY", 1)));       // beyond the negotiated range
        Assert.Throws<NotSupportedException>(() => TwsPlaceOrder.Fields(176, 1, c, new TwsOrder("BUY", 1, "TRAIL")));
        Assert.Throws<NotSupportedException>(() => TwsPlaceOrder.Fields(176, 1, c with { SecType = "OPT" }, TwsOrder.Market("BUY", 1)));
        Assert.Throws<NotSupportedException>(() => TwsPlaceOrder.Fields(100, 1, c, TwsOrder.Market("BUY", 0.5)));     // fractional needs 101
        Assert.Throws<ArgumentException>(() => TwsPlaceOrder.Fields(176, 1, c, new TwsOrder("BUY", 1, "LMT")));
        Assert.Equal("100", TwsPlaceOrder.Fields(100, 1, c, TwsOrder.Market("BUY", 100))[18].ToString());
        Assert.Equal(("EUR", "USD", "CASH", "IDEALPRO"), (TwsContract.Forex("EURUSD").Symbol, TwsContract.Forex("EUR.USD").Currency, TwsContract.Forex("eur/usd").SecType, TwsContract.Forex("EUR_USD").Exchange));
    }
}
